const Cache = {
    data: {},
    set(key, value, ttl = 5000) { this.data[key] = { value, expiry: Date.now() + ttl }; },
    get(key) { const item = this.data[key]; if (!item || Date.now() > item.expiry) return null; return item.value; },
    invalidate(key) { if(key) delete this.data[key]; else this.data = {}; }
};

