const U = {
    money: v => new Intl.NumberFormat('pt-BR', {style:'currency', currency:'BRL'}).format(v||0),
    iso: d => { const tzOffset = d.getTimezoneOffset() * 60000; return (new Date(d.getTime() - tzOffset)).toISOString().split('T')[0]; },
    date: d => { if(!d) return ''; let dateObj = new Date(d); if(d.length === 10) dateObj = new Date(d + 'T12:00:00'); return dateObj.toLocaleString('pt-BR', {day:'2-digit', month:'2-digit', year:'numeric', hour:'2-digit', minute:'2-digit'}); },
    fillTemplate(text, vars) { let out = text || ''; Object.keys(vars || {}).forEach(k => { if (k.startsWith('_')) return; out = out.split(`{${k}}`).join(vars[k] ?? ''); }); return out; },
    getCurrentQuinzenaValue() { let curr = new Date(); let m = String(curr.getMonth() + 1).padStart(2, '0'); let y = curr.getFullYear(); let q = curr.getDate() <= 15 ? 'Q1' : 'Q2'; return `${y}-${m}-${q}`; },
    generateQuinzenasOptions() {
        // Gera apenas atual e próxima para não poluir visualmente
        let html = ''; let curr = new Date();
        for(let i=0; i<2; i++) { 
            let tempDate = new Date(curr.getFullYear(), curr.getMonth(), curr.getDate() + (i*16));
            let tm = String(tempDate.getMonth() + 1).padStart(2, '0'); let ty = tempDate.getFullYear(); let tq = tempDate.getDate() <= 15 ? 'Q1' : 'Q2';
            const icon = tq === 'Q1' ? '1️⃣' : '2️⃣';
            html += `<option value="${ty}-${tm}-${tq}">${icon} ${tq === 'Q1' ? '1ª' : '2ª'} Quinzena (${tempDate.toLocaleString('pt-BR', {month:'long'})}/${ty})</option>`;
        }
        return html;
    },
    getQuinzenaDates(val) { if(!val) return { start: '1970-01-01T00:00:00Z', end: '2099-12-31T23:59:59Z' }; const [y, m, q] = val.split('-'); const lastDay = new Date(y, m, 0).getDate(); if (q === 'Q1') return { start: `${y}-${m}-01T00:00:00Z`, end: `${y}-${m}-15T23:59:59Z` }; return { start: `${y}-${m}-16T00:00:00Z`, end: `${y}-${m}-${lastDay}T23:59:59Z` }; },
    buildExtrato(desp) { let extrato = []; let totalIn = 0, totalOut = 0; (desp || []).forEach(d => { const isIncome = App.inflowCategories.includes(d.category); const valNum = Number(d.amount) || 0; const item = { type: isIncome ? 'in' : 'out', desc: d.description, val: valNum, date: new Date(d.date), category: d.category }; if(isIncome) totalIn += valNum; else totalOut += valNum; extrato.push(item); }); extrato.sort((a, b) => a.date - b.date); let saldoAtual = 0; extrato = extrato.map(item => { saldoAtual += item.type === 'in' ? item.val : -item.val; return { ...item, saldo: saldoAtual }; }); extrato.reverse(); return { extrato, totalIn, totalOut }; },
    formatDesc: (text) => { if(text.includes('| Cliente:')) { const parts = text.split('| Cliente:'); return `${parts[0].trim()}<br><span style="font-size:0.85rem; color:var(--muted); font-weight:normal; margin-top:3px; display:inline-block"><i class="ph ph-user"></i> Cliente: ${parts[1].trim()}</span>`; } return text; },
    initFilters() {
        const opts = this.generateQuinzenasOptions();
        ['filter-comissao-quinzena', 'filter-relatorios'].forEach(id => {
            const el = document.getElementById(id);
            if(el && el.options.length === 0) { el.innerHTML = opts; el.value = this.getCurrentQuinzenaValue(); }
        });
    }
};

const CustomSelect = {
    render(id, placeholder, optionsHtml, onChangeGlobalName = '', initialValue = '') { return `<div class="aqc-custom-select" id="wrapper-${id}" onclick="event.stopPropagation()"><div class="aqc-select-trigger" onclick="CustomSelect.toggle('${id}')"><span id="label-${id}">${placeholder}</span><i class="ph ph-caret-down"></i></div><div class="aqc-select-menu" id="menu-${id}" style="display:none;"><div class="aqc-select-search-box"><input type="text" placeholder="Buscar..." onkeyup="CustomSelect.filter('${id}', this.value)"></div><ul class="aqc-select-options" id="options-${id}">${optionsHtml}</ul></div><input type="hidden" id="${id}" value="${initialValue}" required onchange="${onChangeGlobalName ? onChangeGlobalName + '(this.value)' : ''}"></div>`; },
    toggle(id) { const menu = document.getElementById(`menu-${id}`); const wrapper = document.getElementById(`wrapper-${id}`); const isOpening = menu.style.display === 'none' || menu.style.display === ''; document.querySelectorAll('.aqc-select-menu').forEach(el => el.style.display = 'none'); document.querySelectorAll('.aqc-custom-select').forEach(el => { el.style.zIndex = '1'; if(el.parentElement) el.parentElement.style.zIndex = ''; }); if (isOpening) { menu.style.display = 'flex'; wrapper.style.zIndex = '999999'; if(wrapper.parentElement) { wrapper.parentElement.style.position = 'relative'; wrapper.parentElement.style.zIndex = '999999'; } const rect = wrapper.getBoundingClientRect(); const spaceBelow = window.innerHeight - rect.bottom; if (spaceBelow < 280) { menu.style.top = 'auto'; menu.style.bottom = 'calc(100% + 5px)'; menu.style.boxShadow = '0 -10px 30px rgba(0,0,0,0.25)'; } else { menu.style.top = 'calc(100% + 5px)'; menu.style.bottom = 'auto'; menu.style.boxShadow = '0 10px 30px rgba(0,0,0,0.25)'; } const input = menu.querySelector('input'); if(input) { input.value = ''; CustomSelect.filter(id, ''); input.focus(); } } },
    filter(id, term) { term = term.toLowerCase(); const opts = document.getElementById(`options-${id}`).querySelectorAll('li'); opts.forEach(opt => { if (opt.classList.contains('optgroup-label')) return; const text = opt.innerText.toLowerCase(); opt.style.display = text.includes(term) ? 'block' : 'none'; }); },
    select(id, val, text) { document.getElementById(`label-${id}`).innerText = text; const input = document.getElementById(id); if(val.includes('%7B')) val = decodeURIComponent(val); input.value = val; input.dispatchEvent(new Event('change')); document.getElementById(`menu-${id}`).style.display = 'none'; const wrapper = document.getElementById(`wrapper-${id}`); wrapper.style.zIndex = '1'; if(wrapper.parentElement) wrapper.parentElement.style.zIndex = ''; },
    closeAll() { document.querySelectorAll('.aqc-select-menu').forEach(el => el.style.display = 'none'); document.querySelectorAll('.aqc-custom-select').forEach(el => { el.style.zIndex = '1'; if(el.parentElement) el.parentElement.style.zIndex = ''; }); }
};
