        const { data } = await query; let totalComissao = 0; let rank = {}; let details = []; let profFilterActive = (App.filters.comissoes && App.filters.comissoes.prof_id);
        data.forEach(c => { if(!c.items) return; const clientName = c.clients?.name || 'Cliente'; const dateTimeStr = U.date(c.created_at); const parts = dateTimeStr.split(/[\s,]+/); const dateStr = parts[0]; const timeStr = parts[1] || '00:00'; c.items.forEach(i => { let showCard = false; if (isOwner) { if (profFilterActive) { if (i.prof_id !== App.filters.comissoes.prof_id) return; } showCard = true; } else { if (i.prof_id !== App.user.id) return; showCard = true; } if(i.commission) { const v = (i.price * i.commission) / 100; if (isOwner) { if(i.prof_id) { if(!rank[i.prof_id]) rank[i.prof_id] = { name: i.prof_name, total: 0 }; rank[i.prof_id].total += v; } } if (showCard) { totalComissao += v; details.push({ date: dateStr, time: timeStr, client: clientName, service: i.name, prof_id: i.prof_id, prof_name: i.prof_name, pct: i.commission, val: v, ticket: c.ticket }); } } }); });
        const groupedDetails = {}; details.forEach(d => { if(!groupedDetails[d.date]) groupedDetails[d.date] = []; groupedDetails[d.date].push(d); }); let htmlCards = ''; if (details.length === 0) { htmlCards = '<p>Nenhum registro.</p>'; } else { for (const [date, items] of Object.entries(groupedDetails)) { htmlCards += `<div style="margin-bottom: 25px;"><div style="background: var(--primary-light); padding: 8px 15px; border-radius: 8px; margin-bottom: 15px; display:inline-block;">${date}</div><div class="data-list">`; items.forEach(i => { htmlCards += `<div class="card" style="display:flex; justify-content:space-between; border-left:4px solid #2e7d32;"><div><h4>${i.service}</h4><div style="font-size:0.85rem;"><span>${i.client}</span><span>Horário: ${i.time}</span>${isOwner && !profFilterActive ? `<span>Prof: <b>${i.prof_name}</b></span>` : ''}<span>Ref: ${i.ticket} • Taxa: ${i.pct}%</span></div></div><div class="val" style="color:#2e7d32;">+${U.money(i.val)}</div></div>`; }); htmlCards += `</div></div>`; } }
        let finalHtml = ''; if(isOwner) { const sortedRank = Object.entries(rank).sort((a,b)=>b[1].total-a[1].total); let titleTotal = profFilterActive ? `Comissão de ${App.filters.comissoes.prof_name}` : `Total Comissões`; finalHtml = `<div class="card" style="margin-bottom:20px; background:linear-gradient(135deg, var(--primary), var(--primary-dark)); color:white; padding:2rem;"><h3>${titleTotal}</h3><div class="val" style="color:white; font-size:3rem;">${U.money(totalComissao)}</div></div>`; if (profFilterActive) { finalHtml += `<h3>Detalhamento</h3>${htmlCards}`; } else { finalHtml += `<h3>Ranking</h3><div class="data-grid" style="margin-bottom:30px;">` + sortedRank.map((s,i) => { let color = '#cd7f32'; if(i===0) color='#ffd700'; else if(i===1) color='#c0c0c0'; const profId = s[0]; const profName = s[1].name; const val = s[1].total; return `<div class="card" style="cursor:pointer;" onclick="Actions.filterComissaoByProf('${profId}', '${profName.replace(/'/g, "\\'")}')" ><div style="display:flex; justify-content:space-between;"><h4>${i+1}º ${profName}</h4><i class="ph ph-medal" style="color:${color};"></i></div><div class="val">${U.money(val)}</div><div style="text-align:right;">Ver Detalhes</div></div>`; }).join('') + '</div>'; finalHtml += `<h3>Visão Geral</h3>${htmlCards}`; } } else { finalHtml = `<div class="card" style="margin-bottom:20px; background:var(--primary); color:white; padding:2rem"><h4>Minha Comissão</h4><div class="val" style="color:white; font-size:3rem;">${U.money(totalComissao)}</div></div><h3>Meus Detalhamentos</h3>${htmlCards}`; }
        if(dashContainer) dashContainer.innerHTML = finalHtml;
