        const { data: desp } = await db.from('despesas').select('*').gt('date', startDate).lte('date', range.end); const { extrato, totalIn, totalOut } = U.buildExtrato(desp); const lucro = totalIn - totalOut;
        rc.innerHTML = `<div class="card" style="border-bottom:4px solid #2e7d32"><h4>Faturamento</h4><div class="val" style="color:#2e7d32;">${U.money(totalIn)}</div></div><div class="card" style="border-bottom:4px solid #d32f2f"><h4>Custos</h4><div class="val" style="color:#d32f2f;">-${U.money(totalOut)}</div></div><div class="card" style="background:${lucro>=0?'#e8f5e9':'#ffebee'};"><h4>Líquido</h4><div class="val" style="color:${lucro>=0?'#2e7d32':'#d32f2f'}">${U.money(lucro)}</div></div>`;
        let subDash = { 'Pix':0, 'Dinheiro':0, 'Cartão Crédito':0, 'Cartão Débito':0 }; desp.forEach(d => { if(subDash[d.category] !== undefined) subDash[d.category] += Number(d.amount)||0; });
        document.getElementById('resumo-pagamentos-cards').innerHTML = `<div class="card" style="text-align:center"><p>Pix</p><div class="val" style="color:#00695c">${U.money(subDash['Pix'])}</div></div><div class="card" style="text-align:center"><p>Dinheiro</p><div class="val" style="color:#2e7d32">${U.money(subDash['Dinheiro'])}</div></div><div class="card" style="text-align:center"><p>Crédito</p><div class="val" style="color:#e65100">${U.money(subDash['Cartão Crédito'])}</div></div><div class="card" style="text-align:center"><p>Débito</p><div class="val" style="color:#1565c0">${U.money(subDash['Cartão Débito'])}</div></div>`;
