        if(relContainer) relContainer.innerHTML = htmlDesp; window.currentDespesasData = targetList; window.currentRelatorioTipo = isReceitaFilter ? 'Receitas' : 'Despesas';
        let htmlFluxo = ''; if(extrato.length === 0) { htmlFluxo = '<p style="text-align:center;">Sem movimentação.</p>'; } else { htmlFluxo += `<div style="background:#f9f9f9; padding:15px; display:flex; justify-content:space-around; margin-bottom:15px;"><div>Entradas: <b style="color:#2e7d32">${U.money(totalIn)}</b></div><div>Saídas: <b style="color:#d32f2f">-${U.money(totalOut)}</b></div><div>Líquido: <b style="color:${(totalIn-totalOut)>=0?'#2e7d32':'#d32f2f'}">${U.money(totalIn-totalOut)}</b></div></div>`; htmlFluxo += extrato.map(i => `<div style="display:flex; justify-content:space-between; border-bottom:1px dashed #eee;"><div><b style="color:${i.type==='in'?'#2e7d32':'#d32f2f'}">${i.type==='in'?'[+]':'[-]'}</b> ${U.formatDesc(i.desc)}<br><span>${U.date(i.date)}</span></div><div style="text-align:right"><b>${U.money(i.val)}</b><br><span>Caixa: ${U.money(i.saldo)}</span></div></div>`).join(''); }
        const fluxoContainer = document.getElementById('relatorio-fluxo-conteudo'); if(fluxoContainer) fluxoContainer.innerHTML = htmlFluxo; window.currentFluxoData = extrato; window.currentTotaisFluxo = { receita: totalIn, gasto: totalOut, lucro: totalIn - totalOut };
