        html += `</div>`; cont.innerHTML = html; cont.classList.remove('hidden');
        if(type === 'whatsapp' && window.currentWppVars && window.currentWppVars._kind) { const { data: templates } = await db.from('message_templates').select('*'); const pattern = window.currentWppVars._kind === 'aniversario' ? /anivers/i : /confirma/i; const autoT = (templates || []).find(t => pattern.test(t.title)); if(autoT) { const sel = document.getElementById('wpp-template-sel'); if(sel) { sel.value = autoT.id; Actions.applyTemplate(autoT.id); } } }
